ep_note_script.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let dryRun = body.dryRun == true || req.dryRun == true;
let noteId = str(body.noteId ?? req.noteId ?? "").trim();
let notes = vdb.collection("notes");
let rows = [];
if (noteId != "") {
  let lookup = notes.find({noteId: {$eq: noteId}}, 1);
  rows = lookup.data ?? [];
}
if (leng(rows) == 0 && noteId == "") {
  let fallback = notes.find({}, 1);
  rows = fallback.data ?? [];
}

let nowTs = datetime.now().isoformat();
if (leng(rows) == 0) {
  if (noteId == "") {
    noteId = crypto.uuid();
  }
  let title = str(body.title ?? req.title ?? "Generated note").trim();
  if (title == "") {
    title = "Generated note";
  }
  let done = body.done == true || req.done == true;
  let doc = {noteId: noteId, title: title, done: done};
  if (dryRun) {
    return {ok: true, dryRun: true, created: true, note: doc};
  }
  let createRes = notes.insert(doc);
  if (createRes.ok == false) {
    return {ok: false, statusCode: 500, reason: createRes.error ?? "Failed to create note", noteId: noteId, result: createRes};
  }
  return {ok: true, created: true, noteId: noteId, title: title, done: done, createdAt: nowTs};
}

let note = rows[0];
noteId = str(note.noteId ?? noteId).trim();
let currentTitle = str(note.title ?? "").trim();
let nextTitle = currentTitle.contains("[processed]") ? currentTitle : (currentTitle + " [processed]");
let nextDone = true;
let updatePayload = {title: nextTitle, done: nextDone};

if (dryRun) {
  return {ok: true, dryRun: true, noteId: noteId, update: updatePayload};
}

let updateRes = notes.update({noteId: {$eq: noteId}}, updatePayload);
if (updateRes.ok == false) {
  return {ok: false, statusCode: 500, reason: updateRes.error ?? "Failed to process note", noteId: noteId, result: updateRes};
}

let runs = vdb.collection("note_runs");
let runId = crypto.uuid();
let runRes = runs.insert({runId: runId, noteId: noteId, processedAt: nowTs, title: nextTitle});

return {ok: true, noteId: noteId, processed: true, title: nextTitle, done: nextDone, runId: runId, runRecorded: runRes.ok ?? false};

